mapper.sql:
WHERE d.is_deleted = 0
  AND UPPER(e.class_enum) = 'OUTPATIENT'

    AND d.dispense_time >= #{query.startDate}


    AND d.dispense_time <= #{query.endDate}


    AND d.dispense_enum = #{query.recordType}


    AND d.location_id = #{query.locationId}


    AND (m.name LIKE CONCAT('%', #{query.drugKeyword}, '%')
         OR m.py_str LIKE CONCAT('%', #{query.drugKeyword}, '%')
         OR m.wb_str LIKE CONCAT('%', #{query.drugKeyword}, '%'))


    AND r.rx_type_code = #{query.projectType}

mapper.select:
SELECT



ORDER BY d.dispense_time DESC, d.id DESC
LIMIT #{limit}
